    INSERT INTO bem.eventgage_event_factions (id, event_id, name, description, faction_points, icon_url) VALUES
    ('clan_llama', v_event_id, 'Clan de la Llama', 'Audacia y riesgo: juegan rápido, se la juegan en cada tirada y celebran cada victoria como un rugido.', 0, '/images/ruta-dragon/placeholder/clan_llama.jpg'),
    ('clan_escarcha', v_event_id, 'Clan de la Escarcha', 'Paciencia y estrategia: leen el tablero tres turnos adelante y nunca desperdician una acción.', 0, '/images/ruta-dragon/placeholder/clan_escarcha.jpg'),
    ('clan_tormenta', v_event_id, 'Clan de la Tormenta', 'Caos que une mesas: conversan, negocian y arrastran amigos a cada partida.', 0, '/images/ruta-dragon/placeholder/clan_tormenta.jpg')
    INSERT INTO bem.eventgage_event_avatars (id, event_id, name, description, gender, image_url, image_url_m, image_url_f, default_sp, default_cp, default_dp) VALUES
    ('avatar_cazadora', v_event_id, 'La Cazadora de Dragones', 'Estratega nata: planea la ruta completa antes de dar el primer paso.', NULL, '/images/ruta-dragon/placeholder/avatar_cazadora.jpg', '/images/ruta-dragon/placeholder/avatar_cazadora.jpg', '/images/ruta-dragon/placeholder/avatar_cazadora.jpg', '{"EST": 16, "ING": 12, "SUE": 10, "CAR": 9}'::jsonb, '{"points": 0, "icon": "🪙"}'::jsonb, '{"escamas": 0}'::jsonb),
    ('avatar_explorador', v_event_id, 'El Explorador de Mesas', 'Se sienta en cualquier mesa y confía en que los dados estarán de su lado.', NULL, '/images/ruta-dragon/placeholder/avatar_explorador.jpg', '/images/ruta-dragon/placeholder/avatar_explorador.jpg', '/images/ruta-dragon/placeholder/avatar_explorador.jpg', '{"SUE": 16, "CAR": 12, "ING": 10, "EST": 9}'::jsonb, '{"points": 0, "icon": "🪙"}'::jsonb, '{"escamas": 0}'::jsonb),
    ('avatar_narradora', v_event_id, 'La Narradora', 'Convierte cada partida en una historia y a cada desconocido en compañero de juego.', NULL, '/images/ruta-dragon/placeholder/avatar_narradora.jpg', '/images/ruta-dragon/placeholder/avatar_narradora.jpg', '/images/ruta-dragon/placeholder/avatar_narradora.jpg', '{"CAR": 16, "ING": 13, "EST": 10, "SUE": 8}'::jsonb, '{"points": 0, "icon": "🪙"}'::jsonb, '{"escamas": 0}'::jsonb);
