    INSERT INTO bem.eventgage_event_missions (id, event_id, title, preview, description, image, background, mission_type, unlocks_mission, public, chapter, time_limit_seconds, cp_cost, cp_bet, mechanic) VALUES
    ('guarida_01', v_event_id, 'Guarida 1: VelaMar', 'Responde la pregunta del guardián', 'Los guardianes de VelaMar custodian la escama 1. Responde su pregunta: si aciertas, tu clan suma el doble. Si fallas, la escama es tuya igual.', '/images/ruta-dragon/placeholder/guarida_01.jpg', NULL, 'trivia_quiz', NULL, false, 1, NULL, 0, 0, '{"vendor": "VelaMar", "passport_stop": 1, "rewards": {"xp": 60, "cp": 2, "items": ["escama_01"]}, "faction_impact": {"success": 2, "fail": 1}, "draft_content": true, "note": "Pregunta de cultura general para la demo — reemplazar por la del juego del aliado.", "question": "¿En qué arte decorativo se inspiran las losetas de Azul (2017)?", "options": [{"id": "a", "text": "Los azulejos portugueses", "correct": true}, {"id": "b", "text": "Los vitrales góticos", "correct": false}, {"id": "c", "text": "Los mosaicos romanos", "correct": false}], "correct_message": "¡Exacto! Azul rinde homenaje a los azulejos que decoraron Portugal."}'::jsonb),
    ('guarida_02', v_event_id, 'Guarida 2: Los Juegos Sobre la Mesa', 'Tirada contra el guardián (Estrategia)', 'Los guardianes de Los Juegos Sobre la Mesa te retan a un duelo. Tira el dado: tu Estrategia es tu aliada. Si vences, tu clan suma el doble; si pierdes, la escama es tuya igual.', '/images/ruta-dragon/placeholder/guarida_02.jpg', NULL, 'dice_check', NULL, false, 1, NULL, 0, 0, '{"vendor": "Los Juegos Sobre la Mesa", "passport_stop": 2, "rewards": {"xp": 60, "cp": 2, "items": ["escama_02"]}, "faction_impact": {"success": 2, "fail": 1}, "attribute": "EST"}'::jsonb),
    ('guarida_03', v_event_id, 'Guarida 3: Las Reglas de la Casa', 'Responde la pregunta del guardián', 'Los guardianes de Las Reglas de la Casa custodian la escama 3. Responde su pregunta: si aciertas, tu clan suma el doble. Si fallas, la escama es tuya igual.', '/images/ruta-dragon/placeholder/guarida_03.jpg', NULL, 'trivia_quiz', NULL, false, 1, NULL, 0, 0, '{"vendor": "Las Reglas de la Casa", "passport_stop": 3, "rewards": {"xp": 60, "cp": 2, "items": ["escama_03"]}, "faction_impact": {"success": 2, "fail": 1}, "draft_content": true, "note": "Pregunta de cultura general para la demo — reemplazar por la del juego del aliado.", "question": "En ¡Aventureros al Tren! (Ticket to Ride), ¿qué construyen los jugadores?", "options": [{"id": "a", "text": "Rutas de ferrocarril entre ciudades", "correct": true}, {"id": "b", "text": "Murallas alrededor de castillos", "correct": false}, {"id": "c", "text": "Puertos para barcos mercantes", "correct": false}], "correct_message": "¡Correcto! Y ganó el Spiel des Jahres en 2004."}'::jsonb),
    ('guarida_04', v_event_id, 'Guarida 4: Son Geniales', 'Tirada contra el guardián (Suerte)', 'Los guardianes de Son Geniales te retan a un duelo. Tira el dado: tu Suerte es tu aliada. Si vences, tu clan suma el doble; si pierdes, la escama es tuya igual.', '/images/ruta-dragon/placeholder/guarida_04.jpg', NULL, 'dice_check', NULL, false, 1, NULL, 0, 0, '{"vendor": "Son Geniales", "passport_stop": 4, "rewards": {"xp": 60, "cp": 2, "items": ["escama_04"]}, "faction_impact": {"success": 2, "fail": 1}, "attribute": "SUE"}'::jsonb),
    ('guarida_05', v_event_id, 'Guarida 5: Carlos Reyes', 'Responde la pregunta del guardián', 'Los guardianes de Carlos Reyes custodian la escama 5. Responde su pregunta: si aciertas, tu clan suma el doble. Si fallas, la escama es tuya igual.', '/images/ruta-dragon/placeholder/guarida_05.jpg', NULL, 'trivia_quiz', NULL, false, 1, NULL, 0, 0, '{"vendor": "Carlos Reyes", "passport_stop": 5, "rewards": {"xp": 60, "cp": 2, "items": ["escama_05"]}, "faction_impact": {"success": 2, "fail": 1}, "draft_content": true, "note": "Pregunta de cultura general para la demo — reemplazar por la del juego del aliado.", "question": "¿Quién diseñó Catan, publicado por primera vez en 1995?", "options": [{"id": "a", "text": "Klaus Teuber", "correct": true}, {"id": "b", "text": "Reiner Knizia", "correct": false}, {"id": "c", "text": "Uwe Rosenberg", "correct": false}], "correct_message": "¡Así es! Klaus Teuber, el padre de Catan."}'::jsonb),
    ('guarida_06', v_event_id, 'Guarida 6: Gemu AD (AD164)', 'Tirada contra el guardián (Ingenio)', 'Los guardianes de Gemu AD (AD164) te retan a un duelo. Tira el dado: tu Ingenio es tu aliada. Si vences, tu clan suma el doble; si pierdes, la escama es tuya igual.', '/images/ruta-dragon/placeholder/guarida_06.jpg', NULL, 'dice_check', NULL, false, 1, NULL, 0, 0, '{"vendor": "Gemu AD (AD164)", "passport_stop": 6, "rewards": {"xp": 60, "cp": 2, "items": ["escama_06"]}, "faction_impact": {"success": 2, "fail": 1}, "attribute": "ING"}'::jsonb),
    ('guarida_07', v_event_id, 'Guarida 7: Comunidad Torrikku', 'Responde la pregunta del guardián', 'Los guardianes de Comunidad Torrikku custodian la escama 7. Responde su pregunta: si aciertas, tu clan suma el doble. Si fallas, la escama es tuya igual.', '/images/ruta-dragon/placeholder/guarida_07.jpg', NULL, 'trivia_quiz', NULL, false, 1, NULL, 0, 0, '{"vendor": "Comunidad Torrikku", "passport_stop": 7, "rewards": {"xp": 60, "cp": 2, "items": ["escama_07"]}, "faction_impact": {"success": 2, "fail": 1}, "draft_content": true, "note": "Pregunta de cultura general para la demo — reemplazar por la del juego del aliado.", "question": "¿Cómo se llaman las figuritas de madera con forma de persona que popularizó Carcassonne?", "options": [{"id": "a", "text": "Meeples", "correct": true}, {"id": "b", "text": "Peones", "correct": false}, {"id": "c", "text": "Tótems", "correct": false}], "correct_message": "¡Correcto! \"Meeple\" viene de \"my people\"."}'::jsonb),
    ('guarida_08', v_event_id, 'Guarida 8: BBG', 'Tirada contra el guardián (Carisma)', 'Los guardianes de BBG te retan a un duelo. Tira el dado: tu Carisma es tu aliada. Si vences, tu clan suma el doble; si pierdes, la escama es tuya igual.', '/images/ruta-dragon/placeholder/guarida_08.jpg', NULL, 'dice_check', NULL, false, 1, NULL, 0, 0, '{"vendor": "BBG", "passport_stop": 8, "rewards": {"xp": 60, "cp": 2, "items": ["escama_08"]}, "faction_impact": {"success": 2, "fail": 1}, "attribute": "CAR"}'::jsonb),
    ('guarida_09', v_event_id, 'Guarida 9: Azahar', 'Responde la pregunta del guardián', 'Los guardianes de Azahar custodian la escama 9. Responde su pregunta: si aciertas, tu clan suma el doble. Si fallas, la escama es tuya igual.', '/images/ruta-dragon/placeholder/guarida_09.jpg', NULL, 'trivia_quiz', NULL, false, 1, NULL, 0, 0, '{"vendor": "Azahar", "passport_stop": 9, "rewards": {"xp": 60, "cp": 2, "items": ["escama_09"]}, "faction_impact": {"success": 2, "fail": 1}, "draft_content": true, "note": "Pregunta de cultura general para la demo — reemplazar por la del juego del aliado.", "question": "¿Qué premio alemán, entregado desde 1979, se conoce como el \"Juego del Año\"?", "options": [{"id": "a", "text": "Spiel des Jahres", "correct": true}, {"id": "b", "text": "Golden Geek", "correct": false}, {"id": "c", "text": "As d''Or", "correct": false}], "correct_message": "¡Exacto! El Spiel des Jahres es el premio más famoso del mundo del juego de mesa."}'::jsonb),
    ('guarida_10', v_event_id, 'Guarida 10: Tablero Infinito', 'Tirada contra el guardián (Estrategia)', 'Los guardianes de Tablero Infinito te retan a un duelo. Tira el dado: tu Estrategia es tu aliada. Si vences, tu clan suma el doble; si pierdes, la escama es tuya igual.', '/images/ruta-dragon/placeholder/guarida_10.jpg', NULL, 'dice_check', NULL, false, 1, NULL, 0, 0, '{"vendor": "Tablero Infinito", "passport_stop": 10, "rewards": {"xp": 60, "cp": 2, "items": ["escama_10"]}, "faction_impact": {"success": 2, "fail": 1}, "attribute": "EST"}'::jsonb),
    ('guarida_11', v_event_id, 'Guarida 11: Lafonda Games', 'Responde la pregunta del guardián', 'Los guardianes de Lafonda Games custodian la escama 11. Responde su pregunta: si aciertas, tu clan suma el doble. Si fallas, la escama es tuya igual.', '/images/ruta-dragon/placeholder/guarida_11.jpg', NULL, 'trivia_quiz', NULL, false, 1, NULL, 0, 0, '{"vendor": "Lafonda Games", "passport_stop": 11, "rewards": {"xp": 60, "cp": 2, "items": ["escama_11"]}, "faction_impact": {"success": 2, "fail": 1}, "draft_content": true, "note": "Pregunta de cultura general para la demo — reemplazar por la del juego del aliado.", "question": "En Pandemic (2008), ¿cómo se gana la partida?", "options": [{"id": "a", "text": "Todos juntos: es un juego cooperativo contra el tablero", "correct": true}, {"id": "b", "text": "Gana quien cure más enfermedades", "correct": false}, {"id": "c", "text": "Gana el último jugador en pie", "correct": false}], "correct_message": "¡Correcto! En Pandemic se gana o se pierde en equipo."}'::jsonb),
    ('guarida_12', v_event_id, 'Guarida 12: Friz Froz Fruz', 'Tirada contra el guardián (Suerte)', 'Los guardianes de Friz Froz Fruz te retan a un duelo. Tira el dado: tu Suerte es tu aliada. Si vences, tu clan suma el doble; si pierdes, la escama es tuya igual.', '/images/ruta-dragon/placeholder/guarida_12.jpg', NULL, 'dice_check', NULL, false, 1, NULL, 0, 0, '{"vendor": "Friz Froz Fruz", "passport_stop": 12, "rewards": {"xp": 60, "cp": 2, "items": ["escama_12"]}, "faction_impact": {"success": 2, "fail": 1}, "attribute": "SUE"}'::jsonb),
    ('guarida_13', v_event_id, 'Guarida 13: Woodmood', 'Responde la pregunta del guardián', 'Los guardianes de Woodmood custodian la escama 13. Responde su pregunta: si aciertas, tu clan suma el doble. Si fallas, la escama es tuya igual.', '/images/ruta-dragon/placeholder/guarida_13.jpg', NULL, 'trivia_quiz', NULL, false, 1, NULL, 0, 0, '{"vendor": "Woodmood", "passport_stop": 13, "rewards": {"xp": 60, "cp": 2, "items": ["escama_13"]}, "faction_impact": {"success": 2, "fail": 1}, "draft_content": true, "note": "Pregunta de cultura general para la demo — reemplazar por la del juego del aliado.", "question": "¿Cuántas caras tiene el dado de rol conocido como d20?", "options": [{"id": "a", "text": "20", "correct": true}, {"id": "b", "text": "12", "correct": false}, {"id": "c", "text": "10", "correct": false}], "correct_message": "¡Correcto! El icosaedro, rey de las tiradas críticas."}'::jsonb),
    ('guarida_14', v_event_id, 'Guarida 14: Ronda', 'Tirada contra el guardián (Ingenio)', 'Los guardianes de Ronda te retan a un duelo. Tira el dado: tu Ingenio es tu aliada. Si vences, tu clan suma el doble; si pierdes, la escama es tuya igual.', '/images/ruta-dragon/placeholder/guarida_14.jpg', NULL, 'dice_check', NULL, false, 1, NULL, 0, 0, '{"vendor": "Ronda", "passport_stop": 14, "rewards": {"xp": 60, "cp": 2, "items": ["escama_14"]}, "faction_impact": {"success": 2, "fail": 1}, "attribute": "ING"}'::jsonb),
    ('guarida_15', v_event_id, 'Guarida 15: Devir', 'Responde la pregunta del guardián', 'Los guardianes de Devir custodian la escama 15. Responde su pregunta: si aciertas, tu clan suma el doble. Si fallas, la escama es tuya igual.', '/images/ruta-dragon/placeholder/guarida_15.jpg', NULL, 'trivia_quiz', NULL, false, 1, NULL, 0, 0, '{"vendor": "Devir", "passport_stop": 15, "rewards": {"xp": 60, "cp": 2, "items": ["escama_15"]}, "faction_impact": {"success": 2, "fail": 1}, "draft_content": true, "note": "Pregunta de cultura general para la demo — reemplazar por la del juego del aliado.", "question": "¿En qué ciudad alemana se celebra SPIEL, una de las ferias de juegos de mesa más grandes del mundo?", "options": [{"id": "a", "text": "Essen", "correct": true}, {"id": "b", "text": "Berlín", "correct": false}, {"id": "c", "text": "Múnich", "correct": false}], "correct_message": "¡Exacto! Cada octubre, Essen se llena de mesas."}'::jsonb);
